---@return string
local function GetCurrentCity()

    return GetConvar( 'cityName', 'Santa' )
end

function LoadVehicleConfig()
    local fileUrl = ('config/vehicles/%s.json'):format( GetCurrentCity() )
    local contents = LoadResourceFile( "vrp", fileUrl )
    if contents and #contents > 2 then
        local ok, decoded = pcall(json.decode, contents)
        if ok and type(decoded) == 'table' and next(decoded) then
            List = decoded
        end
    end
end

LoadVehicleConfig()
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLE
-----------------------------------------------------------------------------------------------------------------------------------------
function VehicleType(Name)
	return VehicleTypes[Name]
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLE
-----------------------------------------------------------------------------------------------------------------------------------------
function CheckHeli(Name)
    if List[Name] then
		return List[Name]["Heli"] or (List[Name]["VehicleType"] and List[Name]["VehicleType"] == "heli")
	end
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLEGLOBAL
-----------------------------------------------------------------------------------------------------------------------------------------
function VehicleGlobal()
	return List
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLEEXIST
-----------------------------------------------------------------------------------------------------------------------------------------
function VehicleExist(Name)
	if List[Name] then
		return true
	end

	return false
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLENAME
-----------------------------------------------------------------------------------------------------------------------------------------
function VehicleName(Name)
	if List[Name] then
		return List[Name]["Name"]
	end

	return false
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLECHEST
-----------------------------------------------------------------------------------------------------------------------------------------
function VehicleChest(Name)
	if List[Name] then
		return List[Name]["Weight"]
	end

	return 0
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLEPRICE
-----------------------------------------------------------------------------------------------------------------------------------------
function VehiclePrice(Name)
	if Name and List[Name] and List[Name]["Price"] then
		return tonumber(List[Name]["Price"]) or 0
	end

	return 0
end

function VehicleArmored(Name)
	if List[Name] then
		return List[Name]["Armored"]
	end

	return false
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLEMODE
-----------------------------------------------------------------------------------------------------------------------------------------
function VehicleMode(Name)
	if List[Name] then
		return List[Name]["Mode"]
	end

	return false
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLEMODE
-----------------------------------------------------------------------------------------------------------------------------------------
function VehicleVip(Name)
	if List[Name] then
		return List[Name]["VIP"]
	end

	return false
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLEMODE
-----------------------------------------------------------------------------------------------------------------------------------------
function GetSpawnFromHash(Hash)
    local Select = false
    for Spawn,Info in pairs(List) do
        if Info["hash"] and Info["hash"] == Hash then
            Select = Spawn
            break
        end
    end
	return Select
end
-----------------------------------------------------------------------------------------------------------------------------------------
-- VEHICLEGEMS
-----------------------------------------------------------------------------------------------------------------------------------------
function VehicleGems(Name)
	if List[Name] then
		return List[Name]["Gems"]
	end

	return false
end

function VehicleInfo(Name)
	if List[Name] then
		return List[Name]
	end

	return false
end
